INSERT INTO public.onsen_verdicts (
  target_type, target_slug, level, headline, briefing, items, fact_statuses, status, verified_at, source_file
) VALUES (
  'accommodation', 'yufuin-gorinka', 'full', '객실 노천탕 중심 숙소입니다.', '{"experiences_read":504,"onsen_related":503,"platforms":["구글 지도","라쿠텐","야후 트래블","익스피디아","자란","트립어드바이저"]}'::jsonb, '[{"order":1,"type":"positive","headline":"객실 노천탕이 이 숙소의 주요 판단 기준입니다.","counts":{"mentions":503,"negative":0,"denominator":"onsen_related","platform_count":6,"direction_counts":{"positive":379,"mixed":124,"negative":0,"neutral":0}},"body":"객실 노천탕 관련 평가는 플랫폼을 나눠 봐도 안정적으로 반복됩니다. 이 숙소를 고를 때 먼저 확인할 핵심 온천 경험으로 볼 수 있습니다.","verdict":"객실 노천탕을 우선순위에 두는 여행자라면 비교 가치가 높습니다.","chip_label":"객실 노천탕","adoption_status":"verdict_basis","signal_key":"room_bath_hot_spring","bath_area":"room_open_air_bath","platforms":["구글 지도","라쿠텐","야후 트래블","익스피디아","자란","트립어드바이저"],"season_months":null},{"order":2,"type":"conditional","headline":"예약 조건은 미리 분리해 확인해야 합니다.","counts":{"mentions":118,"negative":0,"denominator":"experiences_read","platform_count":4,"direction_counts":{"positive":79,"mixed":39,"negative":0,"neutral":0}},"body":"예약/운영 조건 관련 평가는 장점과 주의점이 함께 잡힙니다. 플랫폼이 나뉘어도 같은 항목이 반복되므로 예약 조건과 계절 변수를 같이 확인하는 것이 안전합니다.","verdict":"예약 단계에서 객실 타입과 온천 이용 조건을 따로 확인하시기 바랍니다.","chip_label":"예약/운영 조건","adoption_status":"verdict_basis","signal_key":"booking_confusion","bath_area":"room_open_air_bath","platforms":["구글 지도","라쿠텐","야후 트래블","자란"],"season_months":null},{"order":3,"type":"minor","headline":"수질 체감이 선택 기준으로 잡힙니다.","counts":{"mentions":23,"negative":0,"denominator":"onsen_related","platform_count":3,"direction_counts":{"positive":14,"mixed":9,"negative":0,"neutral":0}},"body":"수질 체감은 중심 경험은 아니지만 선택 전에 함께 볼 만한 항목입니다. 다른 핵심 욕장 경험과 나란히 비교하면 숙소의 성격이 더 분명해집니다.","verdict":"수질 체감을 우선순위에 두는 여행자라면 비교 가치가 높습니다.","chip_label":"수질 체감","adoption_status":"verdict_basis","signal_key":"water_texture","bath_area":"room_open_air_bath","platforms":["라쿠텐","야후 트래블","자란"],"season_months":null}]'::jsonb, '[]'::jsonb, 'published', '2026-07-08', 'research/onsen-review-signals/kyushu_deep_research_qa_matrix_2026-07-08.csv'
) ON CONFLICT (target_type, target_slug) DO UPDATE SET
  level = EXCLUDED.level,
  headline = EXCLUDED.headline,
  briefing = EXCLUDED.briefing,
  items = EXCLUDED.items,
  fact_statuses = EXCLUDED.fact_statuses,
  status = EXCLUDED.status,
  verified_at = EXCLUDED.verified_at,
  source_file = EXCLUDED.source_file,
  updated_at = NOW()
WHERE public.onsen_verdicts.level <> 'full' OR EXCLUDED.level = 'full';

